/**
 * Expands vocabulary.json by adding 150 new words to levels 2, 3, and 4.
 * Level 1 remains unchanged. All duplicates removed.
 */
const fs = require('fs');
const path = require('path');

const vocabPath = path.join(__dirname, '..', 'packages', 'server', 'data', 'vocabulary.json');
const data = JSON.parse(fs.readFileSync(vocabPath, 'utf8'));

// Collect all existing english words (lowercase)
const allExisting = new Set();
for (const level of Object.values(data.levels)) {
  for (const w of level.words) allExisting.add(w.english.toLowerCase());
}
console.log('Existing total words:', allExisting.size);

