// ============================================================
// VALIDATE: check no duplicates
// ============================================================
function checkDuplicates(newWords, levelName, tracker) {
  let dupeCount = 0;
  for (const w of newWords) {
    const key = w.english.toLowerCase();
    if (tracker.has(key)) {
      console.warn(`DUPLICATE in ${levelName}: "${w.english}" already exists`);
      dupeCount++;
    }
    tracker.add(key);
  }
  return dupeCount;
}

const tracker = new Set(allExisting);
let totalDupes = 0;
totalDupes += checkDuplicates(level2New, 'Level 2', tracker);
totalDupes += checkDuplicates(level3New, 'Level 3', tracker);
totalDupes += checkDuplicates(level4New, 'Level 4', tracker);

if (totalDupes > 0) {
  console.error(`\nFOUND ${totalDupes} DUPLICATES - ABORTING!`);
  process.exit(1);
}

// Append
data.levels['2'].words.push(...level2New);
data.levels['3'].words.push(...level3New);
data.levels['4'].words.push(...level4New);

console.log('\nFinal counts:');
console.log('Level 1:', data.levels['1'].words.length, 'words');
console.log('Level 2:', data.levels['2'].words.length, 'words (added', level2New.length, ')');
console.log('Level 3:', data.levels['3'].words.length, 'words (added', level3New.length, ')');
console.log('Level 4:', data.levels['4'].words.length, 'words (added', level4New.length, ')');

const total = Object.values(data.levels).reduce((sum, l) => sum + l.words.length, 0);
console.log('Total:', total, 'words');

// Write
fs.writeFileSync(vocabPath, JSON.stringify(data, null, 2), 'utf8');
console.log('\nSuccessfully wrote vocabulary.json');
